+/**
+ *This function adds a hidden raw field for a utc field type.
+ * These are helpful or needed to support tshark checking
+ * in automated test environments.
+ *
+*/
+void zbee_zcl_add_raw_item_for_utc(proto_tree *tree, int hfindex, tvbuff_t *tvb, unsigned offset)
+{
+    proto_item *attr_utc_raw_item = NULL;
+
+    /* The raw integer value is sometimes needed independent of the formatted time for automated tshark checking. */
+    attr_utc_raw_item = proto_tree_add_item(tree, hfindex, tvb, offset, 4, ENC_LITTLE_ENDIAN);
+    proto_item_set_hidden(attr_utc_raw_item);
+} /*zbee_zcl_add_raw_item_for_utc*/
